+    /// Runs a parallel walk over a directory containing a single file on a
+    /// helper thread, where the visitor panics if `visitor_panics` is set.
+    ///
+    /// Returns `None` if the walk did not return within the deadline (i.e.,
+    /// it hung), and otherwise the result of the walk (`Err` if the panic
+    /// propagated out of `WalkParallel::run`).
+    fn parallel_walk_with_deadline(
+        threads: usize,
+        visitor_panics: bool,
+    ) -> Option<std::thread::Result<()>> {
+        let td = tmpdir();
+        wfile(td.path().join("foo.txt"), "");
+        let root = td.path().to_path_buf();
+
+        let (tx, rx) = std::sync::mpsc::channel();
+        std::thread::spawn(move || {
+            let result =
+                std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
+                    WalkBuilder::new(&root)
+                        .threads(threads)
+                        .build_parallel()
+                        .run(|| {
+                            Box::new(move |_| {
+                                if visitor_panics {
+                                    panic!("oops!");
+                                }
+                                WalkState::Continue
+                            })
+                        });
+                }));
+            let _ = tx.send(result);
+        });
+        rx.recv_timeout(std::time::Duration::from_secs(10)).ok()
+    }
+
+    // Reported bug: if the visitor panics, `WalkParallel::run` hangs instead
+    // of returning (propagating the panic). The remaining workers never see
+    // the panicked worker deactivate, so they sleep in `Worker::get_work`
+    // forever.
+    #[test]
+    fn panic_in_parallel_does_not_hang() {
+        let outcome = parallel_walk_with_deadline(40, true);
+        assert!(
+            outcome.is_some(),
+            "WalkParallel::run did not return within 10s after the visitor \
+             panicked (hang)",
+        );
+    }
+
+    // Control: the same walk with a visitor that does not panic returns.
+    #[test]
+    fn no_panic_in_parallel_does_not_hang() {
+        let outcome = parallel_walk_with_deadline(40, false);
+        assert!(matches!(outcome, Some(Ok(()))), "{:?}", outcome);
+    }
+
+    // Control: the same panic with a single worker thread does not hang.
+    #[test]
+    fn panic_in_parallel_single_thread_does_not_hang() {
+        let outcome = parallel_walk_with_deadline(1, true);
+        assert!(outcome.is_some(), "hang with a single worker thread");
+    }
+
